const { PrismaClient } = require('@prisma/client')
const prisma = new PrismaClient()

async function main() {
  const distId = 'cmpz457wx000erwfm7sdp79gx'
  const invoiceId = 'cmqhix4ik000c429wqqx5dlu6' // INV-1008

  // Define products to create for this distributor
  const prodTemplates = [
    {
      name: "Poppik Liplock Liquid Matte Lipstick- 1",
      sku: "SKU-1782221883345-teln6-clone",
      hsn: "33041000",
      costPrice: "117.1",
      baseSellingPrice: "329",
      gstPercentage: "18"
    },
    {
      name: "Poppik Nailpaint- 24",
      sku: "SKU-1782217958723-3sq8x-clone",
      hsn: "33041000",
      costPrice: "45.92",
      baseSellingPrice: "129",
      gstPercentage: "18"
    },
    {
      name: "Poppik Ultra Lashlift Volumizing Mascara",
      sku: "SKU-1782217958766-8hklu-clone",
      hsn: "33041000",
      costPrice: "106.06",
      baseSellingPrice: "298",
      gstPercentage: "18"
    }
  ]

  console.log('Creating products for distributor...')
  const createdProducts = []
  for (const template of prodTemplates) {
    const prod = await prisma.product.create({
      data: {
        ...template,
        currentStock: 100,
        distributorId: distId
      }
    })
    createdProducts.push(prod)
  }

  console.log('Creating invoice items for INV-1008...')
  const item1 = await prisma.invoiceItem.create({
    data: {
      invoiceId: invoiceId,
      productId: createdProducts[0].id,
      distributorId: distId,
      qty: 12,
      costPrice: createdProducts[0].costPrice,
      rate: createdProducts[0].costPrice,
      gstPercentage: createdProducts[0].gstPercentage,
      extraMarginPercentage: 20, // 20% margin
      total: (12 * parseFloat(createdProducts[0].costPrice) * 0.8).toFixed(2)
    }
  })

  const item2 = await prisma.invoiceItem.create({
    data: {
      invoiceId: invoiceId,
      productId: createdProducts[1].id,
      distributorId: distId,
      qty: 24,
      costPrice: createdProducts[1].costPrice,
      rate: createdProducts[1].costPrice,
      gstPercentage: createdProducts[1].gstPercentage,
      extraMarginPercentage: 15,
      total: (24 * parseFloat(createdProducts[1].costPrice) * 0.85).toFixed(2)
    }
  })

  const item3 = await prisma.invoiceItem.create({
    data: {
      invoiceId: invoiceId,
      productId: createdProducts[2].id,
      distributorId: distId,
      qty: 6,
      costPrice: createdProducts[2].costPrice,
      rate: createdProducts[2].costPrice,
      gstPercentage: createdProducts[2].gstPercentage,
      extraMarginPercentage: 0,
      total: (6 * parseFloat(createdProducts[2].costPrice)).toFixed(2)
    }
  })

  // Update invoice totals
  const totalVal = parseFloat(item1.total) + parseFloat(item2.total) + parseFloat(item3.total)
  const taxable = totalVal / 1.18
  const gst = totalVal - taxable

  await prisma.invoice.update({
    where: { id: invoiceId },
    data: {
      taxableValue: taxable.toFixed(2),
      cgst: (gst / 2).toFixed(2),
      sgst: (gst / 2).toFixed(2),
      igst: 0,
      grandTotal: totalVal.toFixed(2)
    }
  })

  console.log('Seeding completed successfully!')
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect())
